    /** @return array<int,array<string,mixed>> */
    public static function all(): array
    {
        return self::ITEMS;
    }

    /** Items whose peak season includes $month (1-12). */
    public static function forMonth(int $month): array
    {
        return array_values(array_filter(
            self::ITEMS,
            fn ($i) => in_array($month, $i['months'], true)
        ));
    }

    /** Items for $month, grouped by category, in CATEGORIES order. */
    public static function forMonthByCategory(int $month): array
    {
        $grouped = [];
        foreach (array_keys(self::CATEGORIES) as $cat) {
            $in = array_values(array_filter(
                self::forMonth($month),
                fn ($i) => $i['category'] === $cat
            ));
            if ($in !== []) {
                $grouped[$cat] = $in;
            }
        }
        return $grouped;
    }

    public static function bySlug(string $slug): ?array
    {
        foreach (self::ITEMS as $i) {
            if ($i['slug'] === $slug) {
                return $i;
            }
        }
        return null;
    }

    /** Other items sharing the most peak months with $slug. */
    public static function related(string $slug, int $limit = 6): array
    {
        $self = self::bySlug($slug);
        if ($self === null) {
            return [];
        }
        $scored = [];
        foreach (self::ITEMS as $i) {
            if ($i['slug'] === $slug) {
                continue;
            }
            $overlap = count(array_intersect($self['months'], $i['months']));
            if ($overlap > 0) {
                $scored[] = ['overlap' => $overlap, 'item' => $i];
            }
        }
        usort($scored, fn ($a, $b) => $b['overlap'] <=> $a['overlap']);
        return array_map(fn ($s) => $s['item'], array_slice($scored, 0, $limit));
    }

    /** Korea time — the page answers "right now", so it must not use UTC. */
    public static function currentMonth(): int
    {
        return (int) (new \DateTimeImmutable('now', new \DateTimeZone('Asia/Seoul')))->format('n');
    }

    public static function monthSlug(int $month): string
    {
        return strtolower(self::MONTHS[$month]);
    }

    public static function monthFromSlug(string $slug): ?int
    {
        foreach (self::MONTHS as $n => $name) {
            if (strtolower($name) === strtolower($slug)) {
                return $n;
            }
        }
        return null;
    }
}
